16	 */
17	public class Simulator
18	{
19	    // Constants representing configuration information for the simulation.
20	    // The default width for the grid.
21	    private static final int DEFAULT_WIDTH = 250;
22	    // The default depth of the grid.
23	    private static final int DEFAULT_DEPTH = 250;
24	    // List of actors in the field.
25	    private List<Actor> actors;
26	    // The probabilities that actors will be created in any given grid position.
27	    private Map<Actor,Double> actorCreationProb; 
