74	        view.setColor(Water_Fern.class, Color.GREEN.brighter());
75	        view.setColor(Alligator.class, Color.LIGHT_GRAY);
76	        view.setColor(Salamander.class, Color.MAGENTA);
77	        view.setColor(Catfish.class, Color.BLACK);
