89	     */
90	    private Map<Actor,Double> createActorCreationProb()
91	    {
92	        Map<Actor,Double> tempMap = new HashMap<>();
93	        Location location = new Location(0, 0);
94	        tempMap.put(new Grass(time, field, location),0.8);
95	        tempMap.put(new Water_Fern(time, field, location),0.9);
96	        tempMap.put(new Salamander(time, field, location),0.5);
97	        tempMap.put(new Catfish(time, field, location),0.7);
98	        tempMap.put(new Lemur(time, field, location),0.45);
99	        tempMap.put(new Panther(time, field, location),0.3);
100	        tempMap.put(new Alligator(time, field, location),0.25);
101	        
102	        
103	        return tempMap;
104	    }
105	
106	    /**
107	     * Create a List of all the diseases in the simulation, specify which actors start with the disease and which actors can catch the disease.
108	     * Starting and affected actors are specified by a Map with a String key and double value, of probability to get disease for starting actors,
109	     * and disease severity for affected actors. Severity ranges from 0.0 to 1.0, 0.0 being completely fatal as soon as contracted, and 1.0 meaning
110	     * the actor is just a disease carrier.
111	     * @return The diseases List.
112	     */
113	    private static List<Disease> createDiseases()
114	    {
115	        List<Disease> list = new ArrayList<>();
116	        Disease dengue = new Disease("dengue", true, true);
117	
118	        dengue.getActorsAffectedMap().put(Lemur.class, 0.9);
119	        dengue.getActorsAffectedMap().put(Panther.class, 0.6);
120	        dengue.getActorsAffectedMap().put(Alligator.class, 0.6);
121	
122	        dengue.getStartingActorsMap().put(Lemur.class, 0.4);
123	        list.add(dengue);
124	
125	        Disease river_fever = new Disease("river_fever", true, false);
126	
127	        river_fever.getActorsAffectedMap().put(Water_Fern.class, 1.0);
