200	    /**
201	     * Randomly populate the field with actors.
202	     * Actors can only populate areas they will survive in
203	     * i.e. actors that will not survive in water cannot be placed there.
204	     */
205	    private void populate()
206	    {
207	        Random rand = Randomizer.getRandom();
208	        field.clear();
209	        for(int row = 0; row < field.getDepth(); row++) {
210	            for(int col = 0; col < field.getWidth(); col++) {
211	                for (Actor actor : actorCreationProb.keySet()){
212	                    Location location = new Location(row, col);
213	                    if((rand.nextDouble() <= actorCreationProb.get(actor)) && ((actor.canMoveOnLand() && actor.canMoveOnWater()) || (field.isUnderWater(location.getRow(), location.getCol()) && actor.canMoveOnWater()) || (!field.isUnderWater(location.getRow(), location.getCol()) && actor.canMoveOnLand()))) {
214	                        Actor newActor = actor.birth(new Location(row, col));
215	                        actors.add(newActor);
216	                        break;
217	                    }
218	                }
219	            }
220	        }
221	    }
222	
223	    /**
224	     * Pause for a given time.
225	     * @param millisec  The time to pause for, in milliseconds
226	     */
227	    private void delay(int millisec)
228	    {
229	        try {
230	            Thread.sleep(millisec);
231	        }
232	        catch (InterruptedException ie) {
233	            // wake up
234	        }
235	    }
236	}
